		FrontierPayloadDescriptor descriptor = new FrontierPayloadDescriptor(FrontierPayloadKind.BASE, generation,
				payload.length, MessageDigest.getInstance("SHA-256").digest(payload));
		Path temporaryPayload = directory.resolve(descriptor.fileName() + ".tmp");
		Path payloadPath = directory.resolve(descriptor.fileName());
		fileOps.writeAndForce(temporaryPayload, payload);
		fileOps.moveAtomically(temporaryPayload, payloadPath);
		fileOps.forceDirectory(directory);

		FrontierManifestStore store = new FrontierManifestStore(directory, fileOps);
		store.publish(new FrontierManifest(generation, descriptor));
